package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)

	var n int
	var m int64
	fmt.Fscan(in, &n, &m)

	a := make([]int, n)
	b := make([]int, n)

	for i := range a {
		fmt.Fscan(in, &a[i])
	}
	var sumB int64
	for i := range b {
		fmt.Fscan(in, &b[i])
		sumB += int64(b[i])
	}

	delta := make([]int, n)
	for i := 0; i < n; i++ {
		delta[i] = a[i] - b[i]
	}

	length := int64(n) * m
	opens := length / 2
	answer := sumB*m + int64(delta[0])

	if opens == 1 {
		fmt.Println(answer)
		return
	}

	period := n
	if n%2 == 0 {
		period = n / 2
	}

	var counts [19]int64
	var cycleAdds [19]int64

	for t := 0; t < period; t++ {
		r1 := (1 + 2*t) % n
		r2 := (2 + 2*t) % n
		cycleAdds[delta[r1]+9]++
		cycleAdds[delta[r2]+9]++
	}

	threshold := 18
	var cumulative int64
	for i := 0; i < 19; i++ {
		cumulative += cycleAdds[i]
		if cumulative > int64(period) {
			threshold = i
			break
		}
	}

	popMin := func() int64 {
		for i := 0; i < 19; i++ {
			if counts[i] > 0 {
				counts[i]--
				return int64(i - 9)
			}
		}
		return 0
	}

	processRound := func(t int) int64 {
		r1 := (1 + 2*t) % n
		r2 := (2 + 2*t) % n
		counts[delta[r1]+9]++
		counts[delta[r2]+9]++
		return popMin()
	}

	remaining := opens - 1
	fullCycles := remaining / int64(period)
	tail := int(remaining % int64(period))

	for fullCycles > 0 {
		var before [19]int64
		copy(before[:], counts[:])

		var cycleCost int64
		for t := 0; t < period; t++ {
			cycleCost += processRound(t)
		}
		answer += cycleCost
		fullCycles--

		stableLower := before[threshold] >= int64(period)
		if stableLower {
			for i := 0; i < threshold; i++ {
				if before[i] != counts[i] {
					stableLower = false
					break
				}
			}
		}

		if stableLower && fullCycles > 0 {
			for i := 0; i < 19; i++ {
				diff := counts[i] - before[i]
				counts[i] += diff * fullCycles
			}
			answer += cycleCost * fullCycles
			fullCycles = 0
		}
	}

	for t := 0; t < tail; t++ {
		answer += processRound(t)
	}

	out := bufio.NewWriter(os.Stdout)
	fmt.Fprintln(out, answer)
	out.Flush()
}

