import (
	"bufio"
	"fmt"
	"os"
)

const negInf int64 = -1 << 60

type transform struct {
	a, b int64
}

func compose(outer, inner transform) transform {
	b := outer.b
	if inner.b != negInf {
		v := inner.b + outer.a
		if v > b {
			b = v
		}
	}
	return transform{
		a: inner.a + outer.a,
		b: b,
	}
}

func power(t transform, exponent int64) transform {
	result := transform{a: 0, b: negInf}
	for exponent > 0 {
		if exponent&1 == 1 {
			result = compose(t, result)
		}
		t = compose(t, t)
		exponent >>= 1
	}
	return result
}

func apply(t transform, x int64) int64 {
	v := x + t.a
	if t.b > v {
		return t.b
	}
	return v
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)

	var n int
	var m int64
	fmt.Fscan(in, &n, &m)

	a := make([]int, n)
	b := make([]int, n)
	delta := make([]int, n)

	for i := range a {
		fmt.Fscan(in, &a[i])
	}

	var base int64
	for i := range b {
		fmt.Fscan(in, &b[i])
		base += int64(b[i])
		delta[i] = a[i] - b[i]
	}
	base *= m

	pairPeriod := n
	if n%2 == 0 {
		pairPeriod = n / 2
	}

	totalPairs := int64(n) * m / 2
	cycles := totalPairs / int64(pairPeriod)

	answer := base
	var previousSelected int64

	for threshold := -9; threshold <= 9; threshold++ {
		cycleTransform := transform{a: 0, b: negInf}

		for k := 0; k < pairPeriod; k++ {
			even := int64(0)
			odd := int64(0)

			if delta[(2*k)%n] <= threshold {
				even = 1
			}
			if delta[(2*k+1)%n] <= threshold {
				odd = 1
			}

			pairTransform := transform{
				a: even + odd - 1,
				b: odd,
			}
			cycleTransform = compose(pairTransform, cycleTransform)
		}

		fullTransform := power(cycleTransform, cycles)
		remaining := apply(fullTransform, 0)

		var perPeriod int64
		for _, d := range delta {
			if d <= threshold {
				perPeriod++
			}
		}

		totalArrivals := perPeriod * m
		selected := totalArrivals - remaining
		exactSelected := selected - previousSelected

		answer += exactSelected * int64(threshold)
		previousSelected = selected
	}

	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	fmt.Fprintln(out, answer)
	out.Flush()
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
)

type item struct {
	weight int64
	index  int
}

func max64(a, b int64) int64 {
	if a > b {
		return a
	}
	return b
}

func rank(mask uint32, n int, m int64) int64 {
	period := n
	if n%2 == 1 {
		period *= 2
	}

	var slack int64
	var allowed int64

	for i := 0; i < period; i++ {
		if i%2 == 1 {
			slack++
		}
		if mask&(uint32(1)<<uint(i%n)) != 0 {
			allowed++
			if slack > 0 {
				slack--
			}
		}
	}

	generated := int64(period / 2)
	d := generated - allowed
	k := slack
	repeats := int64(n) * m / int64(period)

	var q int64
	for repeats > 0 {
		if repeats&1 != 0 {
			q = max64(q+d, k)
		}
		k = max64(k+d, k)
		d *= 2
		repeats >>= 1
	}

	totalCapacity := int64(n) * m / 2
	return totalCapacity - q
}

func main() {
	in := bufio.NewReader(os.Stdin)

	var n int
	var m int64
	fmt.Fscan(in, &n, &m)

	a := make([]int64, n)
	b := make([]int64, n)

	var answer int64
	for i := 0; i < n; i++ {
		fmt.Fscan(in, &a[i])
		answer += a[i] * m
	}
	for i := 0; i < n; i++ {
		fmt.Fscan(in, &b[i])
	}

	items := make([]item, n)
	for i := 0; i < n; i++ {
		items[i] = item{
			weight: b[i] - a[i],
			index:  i,
		}
	}

	sort.Slice(items, func(i, j int) bool {
		return items[i].weight < items[j].weight
	})

	var mask uint32
	var previousRank int64

	for i := 0; i < n; {
		j := i
		for j < n && items[j].weight == items[i].weight {
			mask |= uint32(1) << uint(items[j].index)
			j++
		}

		currentRank := rank(mask, n, m)
		answer += items[i].weight * (currentRank - previousRank)
		previousRank = currentRank
		i = j
	}

	out := bufio.NewWriter(os.Stdout)
	fmt.Fprintln(out, answer)
	out.Flush()
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

func gcd(a, b int) int {
	for b != 0 {
		a, b = b, a%b
	}
	return a
}

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<20)
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()

	var n int
	var m int64
	fmt.Fscan(in, &n, &m)

	a := make([]int, n)
	b := make([]int, n)

	for i := range a {
		fmt.Fscan(in, &a[i])
	}
	var sumB int64
	for i := range b {
		fmt.Fscan(in, &b[i])
		sumB += int64(b[i])
	}

	d := make([]int, n)
	for i := range d {
		d[i] = a[i] - b[i]
	}

	totalLength := int64(n) * m
	opens := totalLength / 2
	answer := sumB*m + int64(d[0])

	stages := opens - 1
	if stages == 0 {
		fmt.Fprintln(out, answer)
		return
	}

	period := n / gcd(n, 2)

	var arrivals [19]int64
	for j := 1; j <= period; j++ {
		x := d[(2*j-1)%n] + 9
		y := d[(2*j)%n] + 9
		arrivals[x]++
		arrivals[y]++
	}

	threshold := 0
	var cumulative int64
	for threshold < 19 {
		cumulative += arrivals[threshold]
		if cumulative >= int64(period) {
			break
		}
		threshold++
	}

	var count [19]int64

	removeMin := func() int {
		for i := 0; i < 19; i++ {
			if count[i] > 0 {
				count[i]--
				return i
			}
		}
		return 0
	}

	remaining := stages

	for remaining >= int64(period) {
		before := count
		var cycleCost int64
		usedAboveThreshold := false

		for j := 1; j <= period; j++ {
			count[d[(2*j-1)%n]+9]++
			count[d[(2*j)%n]+9]++

			v := removeMin()
			cycleCost += int64(v - 9)
			if v > threshold {
				usedAboveThreshold = true
			}
		}

		answer += cycleCost
		remaining -= int64(period)

		stableLow := true
		for i := 0; i < threshold; i++ {
			if count[i] != before[i] {
				stableLow = false
				break
			}
		}

		if stableLow && !usedAboveThreshold && count[threshold] >= before[threshold] {
			fullCycles := remaining / int64(period)
			if fullCycles > 0 {
				answer += fullCycles * cycleCost
				for i := 0; i < 19; i++ {
					count[i] += fullCycles * (count[i] - before[i])
				}
				remaining -= fullCycles * int64(period)
			}
			break
		}
	}

	for j := int64(1); j <= remaining; j++ {
		jj := int(j)
		count[d[(2*jj-1)%n]+9]++
		count[d[(2*jj)%n]+9]++
		answer += int64(removeMin() - 9)
	}

	fmt.Fprintln(out, answer)
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)

	var n int
	var m int64
	fmt.Fscan(in, &n, &m)

	a := make([]int, n)
	b := make([]int, n)
	e := make([]int, n)

	for i := range a {
		fmt.Fscan(in, &a[i])
	}
	for i := range b {
		fmt.Fscan(in, &b[i])
		e[i] = a[i] - b[i]
	}

	var base int64
	for _, x := range b {
		base += int64(x) * m
	}

	period := n
	if n%2 == 0 {
		period = n / 2
	}

	totalChoices := int64(n) * m / 2
	cycles := totalChoices / int64(period)

	answer := base
	var previousSelected int64

	for value := -9; value <= 9; value++ {
		var prefix int64
		minPrefix := int64(1 << 60)

		for t := 0; t < period; t++ {
			left := (2*t - 1 + n) % n
			right := (2 * t) % n

			arrivals := int64(0)
			if e[left] <= value {
				arrivals++
			}
			if e[right] <= value {
				arrivals++
			}

			prefix += arrivals - 1
			if prefix < minPrefix {
				minPrefix = prefix
			}
		}

		cycleDelta := prefix
		if cycleDelta < 0 {
			minPrefix += (cycles - 1) * cycleDelta
		}

		if e[n-1] <= value {
			minPrefix--
		}
		if minPrefix > 0 {
			minPrefix = 0
		}

		selected := totalChoices + minPrefix
		exactlyThisValue := selected - previousSelected
		answer += exactlyThisValue * int64(value)
		previousSelected = selected
	}

	out := bufio.NewWriter(os.Stdout)
	fmt.Fprintln(out, answer)
	out.Flush()
}
